import { CliUsageError } from './errors.mjs';
import { formatPythonStringLiteral } from '../format/python.mjs';

const DECIMAL_INTEGER_PATTERN = /^[+-]?(?:\d+(?:_\d+)*)$/u;
const NEGATIVE_NUMBER_PATTERN = /^-\d+(?:_\d+)*$/u;

export function isNegativeNumberToken(value) {
  return NEGATIVE_NUMBER_PATTERN.test(value.trim());
}

export function parsePythonDecimalInteger(optionName, rawValue) {
  const trimmedValue = rawValue.trim();

  if (!DECIMAL_INTEGER_PATTERN.test(trimmedValue)) {
    throw new CliUsageError(
      `argument ${optionName}: invalid int value: ${formatPythonStringLiteral(rawValue)}`,
    );
  }

  return BigInt(trimmedValue.replace(/_/gu, ''));
}

